144	        }
145	        // A supplied registration date may not be later than the server's current date.
146	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
150	        LocalDate registrationDate = owner.getRegistrationDate();
151	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
152	            .map(Owner::getRegistrationDate)
153	            .filter(registrationDate::equals)
154	            .count();
155	        if (ownersCreatedThatDay >= 100) {
156	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
157	        }
158	        String address = addressNormalizer.normalize(owner.getAddress());
159	        if (address.isBlank()) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        owner.setAddress(address);
163	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
164	        if (telephone == null) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        owner.setTelephone(telephone);
171	        String email = owner.getEmail();
172	        if (email != null) {
173	            email = email.trim();
174	            if (!EMAIL_PATTERN.matcher(email).matches()) {
175	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	            }
177	            owner.setEmail(email.toLowerCase(Locale.ROOT));
178	        }
179	        // A postcode is optional, but when supplied it must be four digits and valid for the
180	        // owner's city per the fixed region table; a city with no known region accepts any
181	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
182	        String postcode = owner.getPostcode();
183	        if (postcode != null) {
184	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
185	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
186	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
187	            }
188	        }
189	        // The owner's telephone and email are now in their canonical, stored form.
190	        // The household id is deterministic: owners with the same normalized last name and
191	        // postcode share it automatically. Assign it unconditionally before the duplicate
192	        // checks so both the household-duplicate rule and the identity-key rule key off the
193	        // same computed id.
194	        owner.setHouseholdId(householdResolver.householdId(owner));
195	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
196	        boolean householdMember = householdResolver.householdExists(owner);
197	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
198	        // existing owner's household is a household duplicate and is rejected with 409. The
199	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
200	        // no longer creates the link, which the deterministic id now does on its own.
201	        if (householdMember && !sharesHousehold) {
202	            return new ResponseEntity<>(HttpStatus.CONFLICT);
203	        }
204	        if (isDuplicateOwner(owner)) {
205	            return new ResponseEntity<>(HttpStatus.CONFLICT);
206	        }
207	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
208	        long ownersInCity = this.clinicService.findAllOwners().stream()
209	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
210	            .count();
211	        if (ownersInCity >= 50) {
212	            return new ResponseEntity<>(HttpStatus.CONFLICT);
213	        }
214	        owner.setCustomerCode(customerCode(owner));
215	        owner.setNamesakeCount(namesakeCount(owner));
216	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
217	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
218	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
219	        // still share an existing owner's last name and postcode while carrying a different
220	        // telephone. When it does, it is created but flagged as a possible duplicate of that
221	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
222	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
223	        // is never flagged.
224	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
225	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
226	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
227	        this.clinicService.saveOwner(owner);
228	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
229	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
230	            ownerMapper.membershipLevel(owner));
231	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
232	        headers.setLocation(UriComponentsBuilder.newInstance()
233	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
234	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
235	    }
236	
237	    /**
238	     * Whether {@code candidate} collides with an already-registered owner under the single
239	     * identity rule enforced on create. This is the one point at which a new owner is
240	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
241	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
242	     * email (or an empty string when absent) and the householdId joined by '|'. The
243	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
244	     * the telephone is part of the key, two members of the same household (same householdId)
245	     * with different telephones have different identityKeys and are both allowed.
246	     *
247	     * <p>The candidate arrives with its telephone and email already normalized and its
248	     * household id already derived, and each existing owner is stored in the same canonical
249	     * form, so an identityKey match means the two owners are genuinely the same identity.
250	     *
251	     * @param candidate the fully-normalized owner about to be created
252	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
253	     */
254	    private boolean isDuplicateOwner(Owner candidate) {
255	        String identityKey = OwnerMapper.identityKey(candidate);
256	        return this.clinicService.findAllOwners().stream()
257	            .map(OwnerMapper::identityKey)
258	            .anyMatch(identityKey::equals);
259	    }
260	
261	    /**
262	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
263	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
264	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
265	     * postcode while carrying a different telephone — a likely re-registration of the same
266	     * person under a new number. Both must supply a postcode for a match to be possible; when
267	     * several existing owners qualify the lowest id is returned so the result is deterministic.
268	     *
269	     * @param candidate the fully-normalized owner about to be created
270	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
271	     */
272	    private Integer possibleDuplicateOf(Owner candidate) {
273	        String postcode = candidate.getPostcode();
274	        if (postcode == null) {
275	            return null;
276	        }
277	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
278	        return this.clinicService.findAllOwners().stream()
279	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
280	                && postcode.equals(existing.getPostcode())
281	                && !postcode.isBlank()
282	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
283	            .map(Owner::getId)
284	            .filter(java.util.Objects::nonNull)
285	            .min(Integer::compareTo)
286	            .orElse(null);
287	    }
288	
289	    /**
290	     * Build the customer code assigned to {@code owner} on create, formatted
291	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
292	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
293	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
294	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
295	     */
296	    private String customerCode(Owner owner) {
297	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
298	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
299	        return region + "-" + hash8;
300	    }
301	
302	    /**
303	     * The number of existing owners that share {@code owner}'s firstName and lastName,
304	     * compared case-insensitively. The candidate is not yet stored at the point this is
305	     * assigned, so it does not count itself. This is the value stored as the owner's
306	     * namesakeCount on create.
307	     */
308	    private int namesakeCount(Owner owner) {
309	        return (int) this.clinicService.findAllOwners().stream()
310	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
311	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
312	            .count();
313	    }
314	
315	    /**
316	     * Roll a registration date forward to the next business day: a Saturday or Sunday
317	     * advances to the following Monday, and a weekday is returned unchanged.
318	     */
319	    private static LocalDate toBusinessDay(LocalDate date) {
320	        return switch (date.getDayOfWeek()) {
321	            case SATURDAY -> date.plusDays(2);
322	            case SUNDAY -> date.plusDays(1);
323	            default -> date;
324	        };
325	    }
326	
327	    /**
328	     * Build the membership number assigned on create, formatted
329	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
330	     * {@code registrationDate} year (e.g. 'NSW-1A2B3C4D-M26').
331	     */
332	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
333	        String yy = String.format("%02d", registrationDate.getYear() % 100);
334	        return customerCode + "-M" + yy;
335	    }
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Override
339	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
340	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
341	        if (currentOwner == null) {
342	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
343	        }
344	        currentOwner.setAddress(ownerFieldsDto.getAddress());
345	        currentOwner.setCity(ownerFieldsDto.getCity());
346	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
347	        currentOwner.setLastName(ownerFieldsDto.getLastName());
348	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
349	        this.clinicService.saveOwner(currentOwner);
350	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
351	    }
352	
353	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
354	    @Transactional
355	    @Override
356	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
357	        Owner owner = this.clinicService.findOwnerById(ownerId);
358	        if (owner == null) {
359	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
360	        }
361	        this.clinicService.deleteOwner(owner);
362	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
363	    }
364	
365	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
366	    @Override
367	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
368	        Owner owner = this.clinicService.findOwnerById(ownerId);
369	        if (owner == null) {
370	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
371	        }
372	        HttpHeaders headers = new HttpHeaders();
373	        Pet pet = petMapper.toPet(petFieldsDto);
374	        owner.setId(ownerId);
375	        pet.setOwner(owner);
376	        pet.getType().setName(null);
377	        this.clinicService.savePet(pet);
378	        PetDto petDto = petMapper.toPetDto(pet);
379	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
380	            .buildAndExpand(pet.getId()).toUri());
381	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
382	    }
383	
384	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
385	    @Override
386	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
387	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
388	        if (currentOwner != null) {
389	            Pet currentPet = this.clinicService.findPetById(petId);
390	            if (currentPet != null) {
391	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
392	                currentPet.setName(petFieldsDto.getName());
393	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
394	                this.clinicService.savePet(currentPet);
395	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
396	            }
397	        }
398	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
399	    }
400	
401	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
402	    @Override
403	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
404	        HttpHeaders headers = new HttpHeaders();
405	        Visit visit = visitMapper.toVisit(visitFieldsDto);
406	        Pet pet = new Pet();
407	        pet.setId(petId);
408	        visit.setPet(pet);
409	        this.clinicService.saveVisit(visit);
410	        VisitDto visitDto = visitMapper.toVisitDto(visit);
411	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
412	            .buildAndExpand(visit.getId()).toUri());
413	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
414	    }
415	
416	
417	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
418	    @Override
419	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
420	        Owner owner = this.clinicService.findOwnerById(ownerId);
421	        if (owner != null) {
422	            Pet pet = owner.getPet(petId);
423	            if (pet != null) {
424	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
425	            }
426	        }
427	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
428	    }
